package com.yeyamo_mobile.api.culture_service.domain;
import static com.yeyamo_mobile.api.culture_service.domain.CultureEnums.*;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="culture_content_translations") public class CultureTranslation{@Id private UUID id;@Column(name="content_id",nullable=false)private UUID contentId;@Column(name="language_code",nullable=false,length=35)private String languageCode;@Column(nullable=false)private String title;private String summary;@Column(columnDefinition="TEXT")private String body;@Column(name="translator_id")private String translatorId;@Enumerated(EnumType.STRING)@Column(nullable=false)private TranslationStatus status;@Column(name="created_at",nullable=false)private Instant createdAt;protected CultureTranslation(){}public static CultureTranslation create(UUID contentId,String language,String title,String summary,String body,String translator){CultureTranslation t=new CultureTranslation();t.id=UUID.randomUUID();t.contentId=contentId;t.languageCode=language;t.title=title;t.summary=summary;t.body=body;t.translatorId=translator;t.status=TranslationStatus.DRAFT;t.createdAt=Instant.now();return t;}public UUID getId(){return id;}public UUID getContentId(){return contentId;}public String getLanguageCode(){return languageCode;}public String getTitle(){return title;}public String getSummary(){return summary;}public String getBody(){return body;}public String getTranslatorId(){return translatorId;}public TranslationStatus getStatus(){return status;}public Instant getCreatedAt(){return createdAt;}public void verify(){status=TranslationStatus.VERIFIED;}}
